<template><section><div class="page-heading"><div><h1>员工</h1><p>管理员工状态、所属部门和初始登录凭据。</p></div><el-button type="primary" :icon="Plus" @click="openCreate">创建员工</el-button></div><div class="filters"><el-input v-model="query" clearable placeholder="搜索员工邮箱" :prefix-icon="Search"/><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="在职" value="active"/><el-option label="停用" value="disabled"/><el-option label="已离职" value="terminated"/></el-select></div><el-table v-loading="loading" :data="filtered"><el-table-column prop="email" label="邮箱" min-width="230"/><el-table-column label="部门" min-width="140"><template #default="{row}">{{ departmentName(row.department_id) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="首次改密" width="110"><template #default="{row}">{{ row.must_change_password ? '待完成' : '已完成' }}</template></el-table-column><el-table-column label="操作" width="230" fixed="right"><template #default="{row}"><el-button text :icon="Edit" :disabled="row.status==='terminated'" @click="openEdit(row)">编辑</el-button><el-button v-if="row.status==='active'" text type="warning" @click="setStatus(row,'disabled')">停用</el-button><el-button v-else-if="row.status==='disabled'" text type="success" @click="setStatus(row,'active')">恢复</el-button><el-button text type="danger" :disabled="row.status==='terminated'" @click="terminate(row)">离职</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!filtered.length" description="暂无匹配员工"/>
<el-dialog v-model="createVisible" title="创建员工" width="min(92vw, 500px)" @closed="resetCreate"><el-alert title="初始密码仅用于本次提交，创建成功后不会显示或保存。" type="warning" :closable="false" class="notice"/><el-form ref="createFormRef" :model="createForm" :rules="createRules" label-position="top"><el-form-item label="邮箱" prop="email"><el-input v-model="createForm.email" autocomplete="off"/></el-form-item><el-form-item label="初始密码" prop="initial_password"><el-input v-model="createForm.initial_password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="部门"><el-select v-model="createForm.department_id" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createEmployee">创建</el-button></template></el-dialog>
<el-dialog v-model="editVisible" title="编辑员工" width="min(92vw, 500px)"><el-form label-position="top"><el-form-item label="邮箱"><el-input :model-value="editing?.email" disabled/></el-form-item><el-form-item label="部门"><el-select v-model="editDepartment" clearable placeholder="不分配部门"><el-option v-for="department in departments" :key="department.id" :label="department.name" :value="department.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveEmployee">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import type{FormInstance,FormRules,TagProps}from'element-plus';import{ElMessage,ElMessageBox}from'element-plus';import{Edit,Plus,Search}from'@element-plus/icons-vue';import{enterpriseAPI}from'@/api/enterprise';import{validatePassword}from'@/features/enterprise/validation';import type{EnterpriseDepartment,EnterpriseEmployee}from'@/types/enterprise';const employees=ref<EnterpriseEmployee[]>([]),departments=ref<EnterpriseDepartment[]>([]),loading=ref(false),saving=ref(false),query=ref(''),statusFilter=ref(''),createVisible=ref(false),editVisible=ref(false),createFormRef=ref<FormInstance>(),editing=ref<EnterpriseEmployee>(),editDepartment=ref<number|null>(null);const createForm=reactive({email:'',initial_password:'',department_id:null as number|null});const createRules:FormRules={email:[{required:true,type:'email',message:'请输入有效邮箱',trigger:'blur'}],initial_password:[{validator:(_r,_v,cb)=>{const m=validatePassword(createForm.initial_password);m?cb(new Error(m)):cb()},trigger:'blur'}]};const filtered=computed(()=>employees.value.filter(e=>(!query.value||e.email.toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||e.status===statusFilter.value)));const departmentName=(id?:number|null)=>departments.value.find(d=>d.id===id)?.name||'未分配';const statusLabel=(s:string)=>({active:'在职',disabled:'停用',terminated:'已离职'}[s]||s);const statusType=(s:string):TagProps['type']=>s==='active'?'success':s==='disabled'?'warning':'info';async function load(){loading.value=true;try{[employees.value,departments.value]=await Promise.all([enterpriseAPI.listEmployees(),enterpriseAPI.listDepartments()])}finally{loading.value=false}}function openCreate(){resetCreate();createVisible.value=true}function resetCreate(){createForm.email='';createForm.initial_password='';createForm.department_id=null;createFormRef.value?.clearValidate()}async function createEmployee(){if(!await createFormRef.value?.validate().catch(()=>false))return;saving.value=true;try{await enterpriseAPI.createEmployee({...createForm});createVisible.value=false;resetCreate();ElMessage.success('员工已创建');await load()}finally{saving.value=false}}function openEdit(row:EnterpriseEmployee){editing.value=row;editDepartment.value=row.department_id??null;editVisible.value=true}async function saveEmployee(){if(!editing.value)return;saving.value=true;try{await enterpriseAPI.updateEmployee(editing.value.id,{status:editing.value.status==='disabled'?'disabled':'active',department_id:editDepartment.value});editVisible.value=false;ElMessage.success('员工信息已更新');await load()}finally{saving.value=false}}async function setStatus(row:EnterpriseEmployee,status:'active'|'disabled'){await enterpriseAPI.updateEmployee(row.id,{status,department_id:row.department_id??null});ElMessage.success(status==='active'?'员工已恢复':'员工已停用');await load()}async function terminate(row:EnterpriseEmployee){await ElMessageBox.confirm(`确认将 ${row.email} 标记为离职？该操作会撤销其会话。`,'员工离职',{type:'warning'});await enterpriseAPI.terminateEmployee(row.id);ElMessage.success('员工已离职');await load()}onMounted(load);</script>
<style scoped>.page-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p{margin:0;color:#64748b}.filters{display:flex;gap:12px;margin-bottom:18px}.filters .el-input{max-width:340px}.filters .el-select{width:160px}.notice{margin-bottom:18px}@media(max-width:640px){.page-heading,.filters{flex-direction:column}.page-heading .el-button,.filters .el-input,.filters .el-select{width:100%;max-width:none}}</style>
